function formatCurrency(value) {
            return new Intl.NumberFormat('en-US', {
                style: 'currency',
                currency: 'INR' // Change this to your desired currency code
            }).format(value);
        }

function handleButtonClick(event) {
   var ja = event.target.id
   if (frappe.user.has_role('Management')) {
   let d = new frappe.ui.Dialog({
    title: 'Enter details',
    fields: [
        {
            label: 'Status',
            fieldname: 'status',
            fieldtype: 'Select',
            options : ["Accepted","Hold","Rejected"],
            reqd:1
        },
        {
            label: 'Comment',
            fieldname: 'comment',
            fieldtype: 'Small Text'
        }
    ],
    size: 'small', // small, large, extra-large 
    primary_action_label: 'Submit',
    primary_action(values) {
        frappe.db.set_value('Job Applicant', ja, {
            status: values.status,
            custom_approval_pending_from_management: 0
        }).then(r => {
            d.hide()
            frappe.msgprint("Status Updated Successfully")
            frappe.db.insert({
                doctype: 'CRM Note', // Replace with actual child doctype name
                 parentfield: 'custom_crm_note',
                 parenttype: 'Job Applicant',
                 parent: ja,
                 added_by: frappe.session.user,
                 added_on:frappe.datetime.now_datetime(),
                 custom_comment_type:"Management Approval",
                 note:values.comment
            })
        })
    }
});

d.show();
}

}
